import json
import os
import re
import shutil
import zipfile

TEMPLATE_PATH = "/root/inventory_report_template.hwpx"
DATA_PATH = "/root/inventory_data.json"
OUTPUT_PATH = "/root/inventory_report_ready.hwpx"
WORK_DIR = "/tmp/hwpx_work"


def load_data(path: str) -> dict:
    with open(path, "r", encoding="utf-8") as f:
        data = json.load(f)
    if not isinstance(data, dict):
        raise ValueError("inventory_data.json must be a JSON object at the top level")
    # Keep values as strings where possible
    flat = {}
    for k, v in data.items():
        if isinstance(v, (dict, list)):
            # Not expected for this task data, but keep as JSON string if present
            flat[k] = json.dumps(v, ensure_ascii=False)
        else:
            flat[k] = "" if v is None else str(v)
    return flat


PLACEHOLDER_RE = re.compile(r"\{\{(.*?)\}\}", re.DOTALL)
PARA_RE = re.compile(r"(<hp:p\b[^>]*>)(.*?)(</hp:p>)", re.DOTALL)

# <hp:t>text</hp:t> OR <hp:t /> (self-closing)
T_OPEN_CLOSE_RE = re.compile(r"<hp:t(\s+[^>]*)?>(.*?)</hp:t>", re.DOTALL)
T_SELFCLOSE_RE = re.compile(r"<hp:t(\s+[^>]*)?\s*/>")

LINESEGARRAY_RE = re.compile(r"<hp:linesegarray>.*?</hp:linesegarray>", re.DOTALL)


def replace_placeholders_in_paragraph(para_xml: str, mapping: dict) -> tuple[str, bool, list[str]]:
    """Return (new_para_xml, changed, unresolved_keys)."""

    # Gather hp:t nodes in order.
    # We'll represent nodes as a list of dicts, each with:
    #  - kind: 'openclose' or 'selfclose'
    #  - attrs: the raw attribute string (including leading space) or ''
    #  - text: inner text (only for openclose)
    #  - span: (start,end) span in para_xml for the whole tag
    #  - inner_span: (start,end) span in para_xml for inner text (only for openclose)

    nodes = []

    # Find all <hp:t ...>...</hp:t> and <hp:t .../> in a single pass by scanning left-to-right.
    # This avoids missing ordering when mixing both forms.
    i = 0
    while True:
        m_open = T_OPEN_CLOSE_RE.search(para_xml, i)
        m_self = T_SELFCLOSE_RE.search(para_xml, i)

        m = None
        kind = None
        if m_open and m_self:
            if m_open.start() < m_self.start():
                m = m_open
                kind = "openclose"
            else:
                m = m_self
                kind = "selfclose"
        elif m_open:
            m = m_open
            kind = "openclose"
        elif m_self:
            m = m_self
            kind = "selfclose"
        else:
            break

        if kind == "openclose":
            attrs = m.group(1) or ""
            text = m.group(2) or ""
            # inner span indices in para_xml
            # Compute by locating group(2) inside match span; easier via offsets.
            inner_start = m.start(2)
            inner_end = m.end(2)
            nodes.append(
                {
                    "kind": kind,
                    "attrs": attrs,
                    "text": text,
                    "span": (m.start(), m.end()),
                    "inner_span": (inner_start, inner_end),
                }
            )
        else:
            attrs = m.group(1) or ""
            nodes.append(
                {
                    "kind": kind,
                    "attrs": attrs,
                    "text": "",
                    "span": (m.start(), m.end()),
                    "inner_span": None,
                }
            )

        i = m.end()

    if not nodes:
        return para_xml, False, []

    # Build concatenated text across openclose nodes (selfclose contributes empty)
    texts = [n["text"] if n["kind"] == "openclose" else "" for n in nodes]
    concat = "".join(texts)

    if "{{" not in concat and "}}" not in concat:
        # Still might have split braces across nodes, but if neither substring exists, there's nothing to do.
        return para_xml, False, []

    # Find placeholders in the concatenated text.
    unresolved = []

    # Precompute node boundaries in concat
    boundaries = []  # (start,end) for each node's text within concat
    pos = 0
    for t in texts:
        start = pos
        pos += len(t)
        end = pos
        boundaries.append((start, end))

    def node_index_at(concat_index: int) -> int:
        # Return node index i such that boundaries[i][0] <= concat_index < boundaries[i][1],
        # or the last node with end==start when at boundary.
        for idx, (s, e) in enumerate(boundaries):
            if s <= concat_index < e:
                return idx
        # If index falls at end (e.g. 0-length or at very end), pick last
        return max(0, len(boundaries) - 1)

    matches = list(PLACEHOLDER_RE.finditer(concat))
    if not matches:
        return para_xml, False, []

    cross_node_needed = False
    for m in matches:
        s, e = m.start(), m.end()
        si = node_index_at(s)
        ei = node_index_at(max(s, e - 1))
        if si != ei:
            cross_node_needed = True
            break

    # Apply replacements to concatenated text first (stable), then redistribute.
    def repl(m: re.Match) -> str:
        key = m.group(1)
        if key in mapping:
            return mapping[key]
        unresolved.append(key)
        return m.group(0)

    new_concat = PLACEHOLDER_RE.sub(repl, concat)

    if new_concat == concat:
        return para_xml, False, unresolved

    if cross_node_needed:
        # Put entire new text into the first openclose <hp:t> we can, blank others.
        first_text_idx = None
        for idx, n in enumerate(nodes):
            if n["kind"] == "openclose":
                first_text_idx = idx
                break

        new_nodes = [dict(n) for n in nodes]

        if first_text_idx is None:
            # No openclose nodes; convert the first selfclose into openclose with text.
            first = new_nodes[0]
            if first["kind"] != "selfclose":
                # Shouldn't happen, but be defensive.
                return para_xml, False, unresolved
            first["kind"] = "openclose"
            first["text"] = new_concat
        else:
            new_nodes[first_text_idx]["text"] = new_concat

        # Blank other openclose nodes' text
        for idx, n in enumerate(new_nodes):
            if idx == first_text_idx:
                continue
            if n["kind"] == "openclose":
                n["text"] = ""

        # Rebuild paragraph XML by replacing node tags from the end to keep spans stable.
        rebuilt = para_xml
        for n, nn in sorted(zip(nodes, new_nodes), key=lambda x: x[0]["span"][0], reverse=True):
            start, end = n["span"]
            if nn["kind"] == "selfclose":
                replacement = f"<hp:t{nn['attrs']} />"
            else:
                replacement = f"<hp:t{nn['attrs']}>{nn['text']}</hp:t>"
            rebuilt = rebuilt[:start] + replacement + rebuilt[end:]

        return rebuilt, True, unresolved

    # No cross-node placeholder: do per-node replacements to minimize changes.
    new_nodes = [dict(n) for n in nodes]
    for idx, n in enumerate(new_nodes):
        if n["kind"] != "openclose":
            continue
        txt = n["text"]
        if "{{" not in txt:
            continue
        # Replace only placeholders that are fully contained in this node
        def repl_local(m: re.Match) -> str:
            key = m.group(1)
            if key in mapping:
                return mapping[key]
            if key not in unresolved:
                unresolved.append(key)
            return m.group(0)

        new_nodes[idx]["text"] = PLACEHOLDER_RE.sub(repl_local, txt)

    rebuilt = para_xml
    changed = False
    for n, nn in sorted(zip(nodes, new_nodes), key=lambda x: x[0]["span"][0], reverse=True):
        if n["kind"] != nn["kind"] or n["text"] != nn["text"]:
            changed = True
        start, end = n["span"]
        if nn["kind"] == "selfclose":
            replacement = f"<hp:t{nn['attrs']} />"
        else:
            replacement = f"<hp:t{nn['attrs']}>{nn['text']}</hp:t>"
        rebuilt = rebuilt[:start] + replacement + rebuilt[end:]

    return rebuilt, changed, unresolved


def process_xml_text(xml_text: str, mapping: dict) -> tuple[str, bool, dict]:
    """Process a single XML document.

    Returns (new_text, changed, stats)
    stats includes: modified_paragraphs, unresolved_keys
    """

    modified_paragraphs = 0
    unresolved_keys = []

    out = []
    last = 0
    changed_any = False

    for m in PARA_RE.finditer(xml_text):
        start, end = m.start(), m.end()
        out.append(xml_text[last:start])
        p_open, p_body, p_close = m.group(1), m.group(2), m.group(3)
        para_full = p_open + p_body + p_close

        new_para, changed, unresolved = replace_placeholders_in_paragraph(para_full, mapping)
        if changed:
            modified_paragraphs += 1
            changed_any = True
            # Remove layout cache only within modified paragraph
            new_para = LINESEGARRAY_RE.sub("", new_para)
        if unresolved:
            unresolved_keys.extend(unresolved)

        out.append(new_para)
        last = end

    out.append(xml_text[last:])
    new_text = "".join(out)

    stats = {
        "modified_paragraphs": modified_paragraphs,
        "unresolved_keys": sorted(set(unresolved_keys)),
    }
    return new_text, changed_any, stats


def main() -> None:
    mapping = load_data(DATA_PATH)

    if os.path.exists(WORK_DIR):
        shutil.rmtree(WORK_DIR)
    os.makedirs(WORK_DIR, exist_ok=True)

    with zipfile.ZipFile(TEMPLATE_PATH, "r") as zf:
        names = zf.namelist()
        zf.extractall(WORK_DIR)

    file_stats = {}

    for name in names:
        path = os.path.join(WORK_DIR, name)
        if not os.path.isfile(path):
            continue

        try:
            with open(path, "r", encoding="utf-8") as f:
                content = f.read()
        except UnicodeDecodeError:
            continue

        if "{{" not in content:
            continue

        new_content, changed, stats = process_xml_text(content, mapping)
        file_stats[name] = {"changed": changed, **stats}

        if changed:
            with open(path, "w", encoding="utf-8") as f:
                f.write(new_content)

    # Repack
    with zipfile.ZipFile(OUTPUT_PATH, "w", compression=zipfile.ZIP_DEFLATED) as outzip:
        for name in names:
            path = os.path.join(WORK_DIR, name)
            if os.path.isfile(path):
                outzip.write(path, name)

    # Final scan inside workdir for remaining placeholders
    remaining = []
    for root, _, files in os.walk(WORK_DIR):
        for fn in files:
            p = os.path.join(root, fn)
            try:
                t = open(p, "r", encoding="utf-8").read()
            except UnicodeDecodeError:
                continue
            if "{{" in t:
                remaining.extend([os.path.relpath(p, WORK_DIR)])

    print("Wrote", OUTPUT_PATH)
    print("File stats:")
    for k in sorted(file_stats.keys()):
        print(" -", k, file_stats[k])
    if remaining:
        print("WARNING: remaining '{{' found in:", remaining)


if __name__ == "__main__":
    main()

