import json
import os
import re
import shutil
import zipfile

TEMPLATE_PATH = "/root/inventory_report_template.hwpx"
DATA_PATH = "/root/inventory_data.json"
OUTPUT_PATH = "/root/inventory_report_ready.hwpx"
WORK_DIR = "/tmp/hwpx_work"


def load_data(path: str) -> dict:
    with open(path, "r", encoding="utf-8") as f:
        data = json.load(f)
    if not isinstance(data, dict):
        raise ValueError("inventory_data.json must be a JSON object at the top level")
    # Keep values as strings where possible
    flat = {}
    for k, v in data.items():
        if isinstance(v, (dict, list)):
            # Not expected for this task data, but keep as JSON string if present
            flat[k] = json.dumps(v, ensure_ascii=False)
        else:
            flat[k] = "" if v is None else str(v)
    return flat


PLACEHOLDER_RE = re.compile(r"\{\{(.*?)\}\}", re.DOTALL)
PARA_RE = re.compile(r"(<hp:p\b[^>]*>)(.*?)(</hp:p>)", re.DOTALL)

# <hp:t>text</hp:t> OR <hp:t /> (self-closing)
T_OPEN_CLOSE_RE = re.compile(r"<hp:t(\s+[^>]*)?>(.*?)</hp:t>", re.DOTALL)
T_SELFCLOSE_RE = re.compile(r"<hp:t(\s+[^>]*)?\s*/>")

LINESEGARRAY_RE = re.compile(r"<hp:linesegarray>.*?</hp:linesegarray>", re.DOTALL)


def replace_placeholders_in_paragraph(para_xml: str, mapping: dict) -> tuple[str, bool, list[str]]:
    """Return (new_para_xml, changed, unresolved_keys)."""

    # Gather hp:t nodes in order.
    # We'll represent nodes as a list of dicts, each with:
    #  - kind: 'openclose' or 'selfclose'
    #  - attrs: the raw attribute string (including leading space) or ''
    #  - text: inner text (only for openclose)
    #  - span: (start,end) span in para_xml for the whole tag
    #  - inner_span: (start,end) span in para_xml for inner text (only for openclose)

    nodes = []

    # Find all <hp:t ...>...</hp:t> and <hp:t .../> in a single pass by scanning left-to-right.
    # This avoids missing ordering when mixing both forms.
    i = 0
    while True:
        m_open = T_OPEN_CLOSE_RE.search(para_xml, i)
        m_self = T_SELFCLOSE_RE.search(para_xml, i)

        m = None
        kind = None
        if m_open and m_self:
            if m_open.start() < m_self.start():
                m = m_open
                kind = "openclose"
            else:
                m = m_self
                kind = "selfclose"
        elif m_open:
            m = m_open
            kind = "openclose"
        elif m_self:
            m = m_self
            kind = "selfclose"
        else:
            break

        if kind == "openclose":
            attrs = m.group(1) or ""
            text = m.group(2) or ""
            # inner span indices in para_xml
            # Compute by locating group(2) inside match span; easier via offsets.
            inner_start = m.start(2)
            inner_end = m.end(2)
            nodes.append(
                {
                    "kind": kind,
                    "attrs": attrs,
                    "text": text,
                    "span": (m.start(), m.end()),
                    "inner_span": (inner_start, inner_end),
                }
            )
        else:
            attrs = m.group(1) or ""
            nodes.append(
                {
                    "kind": kind,
                    "attrs": attrs,
                    "text": "",
                    "span": (m.start(), m.end()),
                    "inner_span": None,
                }
            )

        i = m.end()

    if not nodes:
        return para_xml, False, []

    # Build concatenated text across openclose nodes (selfclose contributes empty)
    texts = [n["text"] if n["kind"] == "openclose" else "" for n in nodes]
    concat = "".join(texts)

    if "{{" not in concat and "}}" not in concat:
        # Still might have split braces across nodes, but if neither substring exists, there's nothing to do.
        return para_xml, False, []

    # Find placeholders in the concatenated text.
    unresolved = []

    # Precompute node boundaries in concat
    boundaries = []  # (start,end) for each node's text within concat
    pos = 0
    for t in texts:
