            if idx == first_text_idx:
                continue
            if n["kind"] == "openclose":
                n["text"] = ""

        # Rebuild paragraph XML by replacing node tags from the end to keep spans stable.
        rebuilt = para_xml
        for n, nn in sorted(zip(nodes, new_nodes), key=lambda x: x[0]["span"][0], reverse=True):
            start, end = n["span"]
            if nn["kind"] == "selfclose":
                replacement = f"<hp:t{nn['attrs']} />"
            else:
                replacement = f"<hp:t{nn['attrs']}>{nn['text']}</hp:t>"
            rebuilt = rebuilt[:start] + replacement + rebuilt[end:]

