        start, end = n["span"]
        if nn["kind"] == "selfclose":
            replacement = f"<hp:t{nn['attrs']} />"
        else:
            replacement = f"<hp:t{nn['attrs']}>{nn['text']}</hp:t>"
        rebuilt = rebuilt[:start] + replacement + rebuilt[end:]

    return rebuilt, changed, unresolved


